import { headers } from "next/headers";
import twilio from "twilio";
import { VoiceResponse } from "twilio/lib/twiml/VoiceResponse";
import { getExternalWebhookUrl } from "@/infra/twilio/webhook-url";

export async function POST(req: Request) {
  const TWILIO_AUTH_TOKEN = process.env.TWILIO_AUTH_TOKEN;
  if (!TWILIO_AUTH_TOKEN) {
    console.error("[twilio voice webhook] TWILIO_AUTH_TOKEN is not set");
    return new Response("Server misconfiguration", { status: 500 });
  }

  const headersList = await headers();
  const signature = headersList.get("x-twilio-signature");
  if (!signature) {
    return new Response("Bad request", { status: 400 });
  }

  const url = await getExternalWebhookUrl(req.url);
  const rawBody = await req.text();
  const params: Record<string, string> = {};
  new URLSearchParams(rawBody).forEach((value, key) => {
    params[key] = value;
  });

  const isValid = twilio.validateRequest(TWILIO_AUTH_TOKEN, signature, url, params);
  if (!isValid) {
    console.error("[twilio voice webhook] Invalid signature");
    return new Response("Unauthorized", { status: 401 });
  }

  try {
    const callSid = params["CallSid"] ?? "";
    console.log(`[twilio voice webhook] Incoming call SID: ${callSid}`);

    // Build TwiML response — customize greeting, recording, hangup as needed
    const twiml = new VoiceResponse();
    twiml.say(
      { voice: "Polly.Joanna", language: "en-US" },
      "Hello! You have reached our automated line. Please leave a message after the beep.",
    );
    twiml.record({
      maxLength: 30,
      playBeep: true,
    });
    twiml.hangup();

    return new Response(twiml.toString(), {
      status: 200,
      headers: { "Content-Type": "text/xml" },
    });
  } catch (err: unknown) {
    console.error("[twilio voice webhook] handler error", err);
    return new Response("Internal error", { status: 500 });
  }
}
